// Turns Gmail Trigger items (Simplify off) and sample-table rows into one email shape.
const TZ = 'Asia/Amman';

function headerValue(headers, key) {
  if (!headers) return '';
  const raw = headers[key] || headers[key.toLowerCase()] || '';
  const s = String(raw);
  // The Gmail Trigger stores whole header lines, e.g. "Auto-Submitted: auto-replied"
  if (s.toLowerCase().startsWith(key.toLowerCase() + ':')) return s.slice(key.length + 1).trim();
  return s.trim();
}

function stripHtml(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

function toAmman(value) {
  let dt = null;
  if (typeof value === 'number') dt = DateTime.fromMillis(value);
  else if (value) {
    dt = DateTime.fromISO(String(value), { setZone: true });
    if (!dt.isValid) dt = DateTime.fromRFC2822(String(value), { setZone: true });
    if (!dt.isValid && /^\d{12,}$/.test(String(value))) dt = DateTime.fromMillis(Number(value));
  }
  if (!dt || !dt.isValid) dt = DateTime.now();
  return dt.setZone(TZ).toISO({ suppressMilliseconds: true });
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.sample_id) {
    out.push({
      json: {
        source: 'sample',
        sample_id: String(j.sample_id),
        message_id: String(j.message_id || ''),
        thread_id: String(j.thread_id || ''),
        in_reply_to: String(j.in_reply_to || ''),
        from_name: String(j.from_name || ''),
        from_email: String(j.from_email || '').toLowerCase().trim(),
        to_email: String(j.to_email || ''),
        cc: String(j.cc || ''),
        subject: String(j.subject || ''),
        body: String(j.body || ''),
        received_at: toAmman(j.received_at),
        auto_submitted: String(j.auto_submitted || ''),
        list_unsubscribe: String(j.list_unsubscribe || ''),
        gmail_labels: '',
        automation_header: '',
      },
    });
    continue;
  }
  const from = (j.from && j.from.value && j.from.value[0]) || {};
  const headers = j.headers || {};
  out.push({
    json: {
      source: 'gmail',
      sample_id: '',
      message_id: String(j.messageId || headerValue(headers, 'message-id') || j.id || ''),
      thread_id: String(j.threadId || ''),
      in_reply_to: String(j.inReplyTo || headerValue(headers, 'in-reply-to') || ''),
      from_name: String(from.name || ''),
      from_email: String(from.address || '').toLowerCase().trim(),
      to_email: String((j.to && j.to.text) || ''),
      cc: String((j.cc && j.cc.text) || ''),
      subject: String(j.subject || ''),
      body: String(j.text || stripHtml(j.html) || j.snippet || ''),
      received_at: toAmman(j.date || (j.internalDate ? Number(j.internalDate) : '')),
      auto_submitted: headerValue(headers, 'auto-submitted'),
      list_unsubscribe: headerValue(headers, 'list-unsubscribe'),
      gmail_labels: Array.isArray(j.labelIds) ? j.labelIds.join(',') : '',
      automation_header: headerValue(headers, 'x-xp-automation'),
    },
  });
}
return out;

// Oldest first, so replies and resends are processed after the email they refer to.
// A Message-ID seen twice in the same batch is kept once; the copy is flagged and only logged.
const cfg = $('Settings').first().json;
const ms = (s) => {
  const d = DateTime.fromISO(String(s || ''), { setZone: true });
  return d.isValid ? d.toMillis() : 0;
};
const items = $input.all().map((i) => i.json);
items.sort((a, b) => ms(a.received_at) - ms(b.received_at));
const seen = new Set();
const out = items.map((e) => {
  const dup = seen.has(e.message_id);
  seen.add(e.message_id);
  return { json: { ...e, duplicate_delivery: dup } };
});
const limit = Number(cfg.cfg_batch_limit) || 0;
return limit > 0 ? out.slice(0, limit) : out;

// Run summary: counts per lane and priority, the Needs Review queue with reasons, failed ClickUp actions.
// With labeled sample emails it also scores the decisions.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.message_id);
const count = (arr, key) => arr.reduce((acc, r) => { const k = r[key] || '(none)'; acc[k] = (acc[k] || 0) + 1; return acc; }, {});
const result = {
  processed: rows.length,
  by_lane: count(rows, 'lane'),
  mode: rows.length ? rows[0].mode : '',
  failed_actions: rows.filter((r) => r.action_ok === false).map((r) => ({ subject: r.subject, reason: r.reason })),
  by_priority: count(rows.filter((r) => r.lane === 'AUTO_CREATE' || r.lane === 'HUMAN_REVIEW'), 'priority'),
  tasks_created: rows.filter((r) => r.lane === 'AUTO_CREATE').map((r) => ({ title: r.title, priority: r.priority, due_date: r.due_date })),
  needs_review: rows.filter((r) => r.lane === 'HUMAN_REVIEW').map((r) => ({ title: r.title, priority: r.priority, reason: r.reason })),
};

let samples = [];
try { samples = $('Get sample emails').all().map((i) => i.json); } catch (e) { samples = []; }
const scored = rows.filter((r) => r.sample_id);
if (samples.length && scored.length) {
  const inSet = (val, spec) => String(spec || '').split('|').map((s) => s.trim()).filter(Boolean).includes(String(val || ''));
  const bySample = {};
  scored.forEach((r) => { bySample[r.sample_id] = r; });
  const evals = [];
  samples.forEach((s) => {
    const r = bySample[s.sample_id];
    if (!r) return;
    const e = { sample_id: s.sample_id, split: s.split, expected_lane: s.acceptable_lanes, lane: r.lane, lane_ok: inSet(r.lane, s.acceptable_lanes) };
    if (s.exp_priority) { e.expected_priority = s.exp_priority; e.priority = r.priority; e.priority_ok = inSet(r.priority, s.exp_priority); }
    if (s.exp_category) { e.expected_category = s.exp_category; e.category = r.category; e.category_ok = inSet(r.category, s.exp_category); }
    if (s.exp_owner) { e.owner_ok = inSet(r.owner, s.exp_owner); }
    if (s.exp_due) { e.expected_due = s.exp_due; e.due = r.due_date; e.due_ok = r.due_date === s.exp_due; }
    e.missed_request = s.exp_lane !== 'LOG_ONLY' && r.lane === 'LOG_ONLY' && !e.lane_ok;
    e.wrongly_auto_created = r.lane === 'AUTO_CREATE' && !e.lane_ok;
    evals.push(e);
  });
  const acc = (arr, k) => {
    const xs = arr.filter((x) => typeof x[k] === 'boolean');
    if (!xs.length) return null;
    const ok = xs.filter((x) => x[k]).length;
    return ok + '/' + xs.length + ' (' + Math.round((100 * ok) / xs.length) + '%)';
  };
  const block = (arr) => ({ emails: arr.length, lane: acc(arr, 'lane_ok'), priority: acc(arr, 'priority_ok'), category: acc(arr, 'category_ok'), owner: acc(arr, 'owner_ok'), due_date: acc(arr, 'due_ok') });
  result.evaluation = {
    all: block(evals),
    dev: block(evals.filter((x) => x.split === 'dev')),
    holdout: block(evals.filter((x) => x.split === 'holdout')),
    missed_requests: evals.filter((x) => x.missed_request).map((x) => x.sample_id),
    wrongly_auto_created: evals.filter((x) => x.wrongly_auto_created).map((x) => x.sample_id),
    mismatches: evals.filter((x) => x.lane_ok === false || x.priority_ok === false || x.category_ok === false || x.due_ok === false || x.owner_ok === false),
  };
}
const lanes = result.by_lane;
result.headline = 'Processed ' + rows.length + ' email(s) in ' + (result.mode || '?') + ' mode: '
  + (lanes.AUTO_CREATE || 0) + ' task(s) in To Do, ' + (lanes.HUMAN_REVIEW || 0) + ' in Needs Review, '
  + (lanes.FOLLOW_UP_COMMENT || 0) + ' added as comments, ' + (lanes.LOG_ONLY || 0) + ' logged only'
  + (result.failed_actions.length ? ', ' + result.failed_actions.length + ' ClickUp action(s) failed' : '')
  + (result.evaluation ? '. Lane accuracy ' + result.evaluation.all.lane : '') + '.';
// Run record for the monitoring dashboard (sent by the next nodes when cfg_monitor_url is set)
const cfg = $('Settings').first().json;
const n = (lane) => rows.filter((r) => r.lane === lane).length;
let fetched = null;
let batched = null;
try { fetched = $('Skip already processed').all().length; } catch (e) { fetched = null; }
try { batched = $('Order & de-duplicate batch').all().length; } catch (e) { batched = null; }
const started = String(cfg.cfg_run_started_at || '');
const finished = DateTime.now().setZone(cfg.cfg_timezone || 'Asia/Amman').toISO();
const startedMs = Date.parse(started);
const ev = result.evaluation;
result.run = {
  execution_id: String($execution.id),
  workflow_id: String($workflow.id),
  started_at: started,
  finished_at: finished,
  duration_sec: Number.isFinite(startedMs) ? Math.round((Date.now() - startedMs) / 100) / 10 : null,
  mode: result.mode,
  source: rows.length ? rows[0].source : '',
  processed: rows.length,
  to_do: n('AUTO_CREATE'),
  needs_review: n('HUMAN_REVIEW'),
  comments: n('FOLLOW_UP_COMMENT'),
  logged: n('LOG_ONLY'),
  failed_actions: rows.filter((r) => r.action_ok === false).length,
  ai_failures: rows.filter((r) => r.ai_ok === false).length,
  batch_limit: Number(cfg.cfg_batch_limit) || null,
  batch_limit_hit: fetched !== null && batched !== null && fetched > batched,
  prompt_version: String(cfg.cfg_prompt_version || ''),
  eval_lane: ev ? ev.all.lane || '' : '',
  eval_priority: ev ? ev.all.priority || '' : '',
  eval_category: ev ? ev.all.category || '' : '',
  eval_owner: ev ? ev.all.owner || '' : '',
  eval_due: ev ? ev.all.due_date || '' : '',
  eval_emails: ev ? ev.all.emails : null,
  mismatches: ev ? ev.mismatches : [],
};
result.monitor_url = String(cfg.cfg_monitor_url || '').trim();
return [{ json: result }];

// Deterministic checks before any AI call: noise, known thread, sender context, prompt inputs.
let email = null;
try { email = $('Loop over emails').first(1).json; } catch (e) { email = null; }
if (!email || !email.message_id) { email = $('Loop over emails').first().json; }
const cfg = $('Settings').first().json;
const TZ = cfg.cfg_timezone || 'Asia/Amman';
const MODE = String(cfg.cfg_mode || 'mock').toLowerCase();

const lower = (s) => String(s == null ? '' : s).toLowerCase().trim();
const safe = (s) => String(s == null ? '' : s).replace(/\{/g, '(').replace(/\}/g, ')');
const list = (s, sep) => String(s || '').split(sep || ',').map((x) => lower(x)).filter(Boolean);

// Task map rows from the same mode only (mock ids never mix with real ClickUp ids)
const allTasks = $('Load task map').all().map((i) => i.json).filter((r) => r && r.task_id);
const tasks = allTasks.filter((t) => (MODE === 'live') !== String(t.task_id).startsWith('MOCK-'));
const rules = $('Load routing rules').all().map((i) => i.json).filter((r) => r && r.category);

const fromEmail = lower(email.from_email);
const fromDomain = fromEmail.split('@')[1] || '';
const subject = String(email.subject || '');

function stripQuoted(text) {
  const lines = String(text || '').replace(/\r\n/g, '\n').split('\n');
  const kept = [];
  for (const line of lines) {
    const t = line.trim();
    if (/^On .{5,250} wrote:$/i.test(t) || /^في .{5,250} كتب:?$/.test(t) || /^-{2,}\s*Original Message\s*-{2,}/i.test(t)) break;
    if (t.startsWith('>')) continue;
    kept.push(line);
  }
  return kept.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}
const bodyClean = stripQuoted(email.body).slice(0, 4000);

// Who is writing? (cfg_client_domains accepts domains or full addresses, e.g. someone@gmail.com:Nour Foods)
const clientMap = {};
String(cfg.cfg_client_domains || '').split(';').forEach((p) => {
  const i = p.indexOf(':');
  if (i > 0) clientMap[lower(p.slice(0, i))] = p.slice(i + 1).trim();
});
const isInternal = list(cfg.cfg_internal_domains).includes(fromDomain) || list(cfg.cfg_known_senders).includes(fromEmail);
const senderClient = clientMap[fromEmail] || clientMap[fromDomain] || '';
const senderKind = isInternal ? 'internal' : (senderClient ? 'client' : 'unknown_external');
const isVip = list(cfg.cfg_vip_senders).includes(fromEmail);

// Noise rules (no AI needed)
const auto = lower(email.auto_submitted);
let noise = '';
if (email.duplicate_delivery) noise = 'duplicate_delivery';
else if (email.automation_header) noise = 'own_automation';
else if (auto && auto !== 'no') noise = 'auto_reply';
else if (/^(automatic reply|auto[- ]?reply|out of office|ooo\b|رد تلقائي)/i.test(subject.trim())) noise = 'auto_reply';
else if (email.list_unsubscribe) noise = 'newsletter';
else if (/^(invitation|updated invitation|accepted|declined|tentative(ly accepted)?|canceled event|cancelled event)\s*[:@]/i.test(subject.trim())) noise = 'calendar';
else if (/^(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?)@/i.test(fromEmail) || /(^|\.)clickup\.com$/i.test(fromDomain)) noise = 'system_notification';
else if (String(email.gmail_labels || '').split(',').includes('CATEGORY_PROMOTIONS')) noise = 'newsletter';

const NOISE_REASON = {
  duplicate_delivery: 'Same Message-ID arrived twice in this batch: the first copy is processed, this copy is only logged',
  own_automation: 'Sent by this automation (X-XP-Automation header): ignored to prevent loops',
  auto_reply: 'Auto-reply / out-of-office (Auto-Submitted header or subject): no task',
  newsletter: 'Newsletter or bulk mail (List-Unsubscribe header or Promotions label): no task',
  calendar: 'Calendar invitation or response: no task',
  system_notification: 'System notification from a no-reply sender: no task',
};

// Email already linked to a task through its thread (or In-Reply-To)?
const threadTask = tasks.find((t) => email.thread_id && t.thread_id === email.thread_id)
  || tasks.find((t) => email.in_reply_to && t.message_id === email.in_reply_to);

// Business calendar for the model (Sunday–Thursday work week)
const holidays = list(cfg.cfg_holidays);
const recv = DateTime.fromISO(String(email.received_at), { setZone: true }).setZone(TZ);
const isBiz = (d) => d.weekday !== 5 && d.weekday !== 6 && !holidays.includes(d.toISODate());
const cal = [];
let n = 0;
for (let i = 0; i <= 16; i++) {
  const d = recv.startOf('day').plus({ days: i });
  let tag;
  if (!isBiz(d)) tag = 'weekend or holiday';
  else if (i === 0) tag = 'business day (the day the email arrived)';
  else { n += 1; tag = 'business day +' + n; }
  cal.push(d.toFormat('ccc yyyy-LL-dd') + ' : ' + tag + (i === 1 ? ' (tomorrow on the calendar)' : ''));
}

const recent = tasks.slice(0, 25).map((t) => '- ' + t.task_id + ' | ' + safe(t.title) + ' | client: ' + (safe(t.client_name) || '-')
  + ' | requester: ' + lower(t.requester_email) + ' | created ' + String(t.created_at || '').slice(0, 10)).join('\n') || '(none yet)';

const promptEmail = [
  'From: ' + safe(email.from_name) + ' <' + fromEmail + '>',
  'To: ' + safe(email.to_email),
  email.cc ? 'Cc: ' + safe(email.cc) : null,
  'Subject: ' + safe(subject),
  'Received: ' + recv.toFormat('cccc yyyy-LL-dd HH:mm') + ' (' + TZ + ')',
  '',
  safe(bodyClean) || '(empty body)',
].filter((l) => l !== null).join('\n');

const promptSender = senderKind === 'internal'
  ? 'Internal colleague' + (isVip ? ' (General Manager, VIP)' : '') + ': ' + safe(email.from_name) + ' <' + fromEmail + '>.'
  : (senderKind === 'client'
    ? 'Client contact from ' + senderClient + ' (known client domain ' + fromDomain + ').'
    : 'External sender, not in the contacts list yet (' + fromDomain + '). This is normal for new clients and personal addresses: judge the email only by its content.');

const base = {
  source: email.source, sample_id: email.sample_id || '', message_id: email.message_id, thread_id: email.thread_id,
  in_reply_to: email.in_reply_to || '', from_name: email.from_name || '', from_email: fromEmail,
  to_email: email.to_email || '', cc: email.cc || '', subject, body_clean: bodyClean,
  received_at: email.received_at, received_local: recv.toFormat('ccc d LLL yyyy HH:mm'),
  sender_kind: senderKind, sender_client: senderClient, is_vip: isVip,
  needs_ai: false, lane: '', reason: '', request_type: '', is_request: false,
  title: '', summary: '', category: '', client_name: senderClient, priority: '', priority_num: null,
  due_date: '', due_iso: '', due_has_time: false, due_source: '', language: '',
  owner_name: '', owner_role: '', owner_email: '', assignee_ids: [],
  confidence: null, ai_ok: null, flags: [], tags: [],
  target_task_id: '', target_task_url: '', target_task_title: '', map_thread: false,
  task_title: '', task_description: '', comment_text: '', ai_rationale: '', clarifying_question: '',
  prompt_email: promptEmail, prompt_sender: promptSender, prompt_calendar: cal.join('\n'), prompt_recent_tasks: recent,
  task_candidates: tasks.slice(0, 50).map((t) => ({
    task_id: String(t.task_id), task_url: t.task_url || '', title: t.title || '', requester_email: lower(t.requester_email),
    client_name: t.client_name || '', list_name: t.list_name || '',
  })),
  routing_rules: rules.map((r) => ({
    category: r.category, owner_name: r.owner_name || '', owner_role: r.owner_role || '',
    owner_email: r.owner_email || '', clickup_user_id: String(r.clickup_user_id || ''),
  })),
};

if (noise) {
  return [{ json: { ...base, lane: 'LOG_ONLY', request_type: noise, reason: NOISE_REASON[noise], confidence: 1, flags: ['rule_' + noise] } }];
}

if (threadTask) {
  const comment = 'Follow-up email received ' + base.received_local + ' (Amman) from ' + (email.from_name || fromEmail) + ' <' + fromEmail + '>\n'
    + 'Subject: ' + subject + '\n\n' + bodyClean.slice(0, 1500)
    + '\n\n(Added by the intake automation: this email is a reply in a thread already linked to this task, so no new task was created.)';
  return [{
    json: {
      ...base, lane: 'FOLLOW_UP_COMMENT', request_type: 'thread_follow_up', is_request: true, confidence: 1,
      reason: 'Reply in an email thread already linked to task ' + threadTask.task_id + ': added as a comment, no duplicate task',
      target_task_id: String(threadTask.task_id), target_task_url: threadTask.task_url || '', target_task_title: threadTask.title || '',
      comment_text: comment, flags: ['rule_known_thread'],
    },
  }];
}

return [{ json: { ...base, needs_ai: true } }];

