parameters.jsCode:
// Business rules on top of the AI proposal: due dates, priority guardrails, owner, duplicates, lane.
const pre = $('Pre-check email').first().json;
const cfg = $('Settings').first().json;
const TZ = cfg.cfg_timezone || 'Asia/Amman';
const raw = $input.item.json || {};
const ai = raw.output && typeof raw.output === 'object' ? raw.output : null;
const aiError = raw.error ? String(raw.error.message || raw.error) : '';
const A = ai || {};

const lower = (s) => String(s == null ? '' : s).toLowerCase().trim();
const txt = (s) => String(s == null ? '' : s).trim();
const d = { ...pre, needs_ai: false };
const flags = new Set();
const prNotes = [];
const dueNotes = [];

// ---------- calendar helpers (Sunday–Thursday work week) ----------
const holidays = String(cfg.cfg_holidays || '').split(',').map((s) => s.trim()).filter(Boolean);
const isBiz = (x) => x.weekday !== 5 && x.weekday !== 6 && !holidays.includes(x.toISODate());
const onOrAfterBiz = (x) => { let y = x; while (!isBiz(y)) y = y.plus({ days: 1 }); return y; };
const prevBiz = (x) => { let y = x.minus({ days: 1 }); while (!isBiz(y)) y = y.minus({ days: 1 }); return y; };
const addBiz = (x, k) => {
  if (k <= 0) return onOrAfterBiz(x);
  let y = x; let c = 0;
  while (c < k) { y = y.plus({ days: 1 }); if (isBiz(y)) c += 1; }
  return y;
};
const bizBetween = (a, b) => {
  if (b <= a) return 0;
  let y = a; let c = 0;
  while (y < b) { y = y.plus({ days: 1 }); if (isBiz(y)) c += 1; }
  return c;
};
const fmt = (x) => x.toFormat('ccc d LLL yyyy');
const recv = DateTime.fromISO(String(pre.received_at), { setZone: true }).setZone(TZ);
const recvDay = recv.startOf('day');

const CATS = ['transformation_pmo', 'org_people', 'data_bi', 'ai_automation_systems', 'creative_design', 'marketing_growth', 'clients_proposals', 'operations_admin', 'other'];
const PRIOS = ['urgent', 'high', 'normal', 'low'];
const RANK = { urgent: 1, high: 2, normal: 3, low: 4 };
const LABEL = { urgent: 'Urgent', high: 'High', normal: 'Normal', low: 'Low' };

// ---------- AI fields (or safety-net defaults) ----------
d.ai_ok = !!ai;
if (!ai) flags.add('ai_failed');
d.is_request = ai ? A.is_request === true : true;
d.request_type = ai ? txt(A.request_type || 'other') : 'unknown';
d.category = CATS.includes(A.category) ? A.category : 'other';
d.client_name = txt(A.client_name) || pre.sender_client || '';
d.title = (txt(A.title) || ('Read and handle email: ' + pre.subject)).replace(/\s+/g, ' ').slice(0, 100);
d.summary = txt(A.summary) || (ai ? '' : 'The AI step failed, so this email was not classified automatically. Please read it and create the right task.');
d.language = ['en', 'ar', 'mixed'].includes(A.language) ? A.language : '';
let conf = Number(A.confidence);
if (!Number.isFinite(conf)) conf = 0;
conf = Math.max(0, Math.min(1, conf));
d.confidence = Math.round(conf * 100) / 100;
(Array.isArray(A.risk_flags) ? A.risk_flags : []).forEach((f) => flags.add(String(f)));
// Several asks: one task with a checklist when they share an owner; Needs Review (split per team) when they need different owners
const subs = (Array.isArray(A.sub_requests) ? A.sub_requests : [])
  .map((s) => (s && typeof s === 'object' ? { ask: txt(s.ask), category: CATS.includes(s.category) ? s.category : d.category } : { ask: txt(s), category: d.category }))
  .filter((s) => s.ask);
const subCats = [...new Set(subs.map((s) => s.category))];
flags.delete('multiple_requests');
if (subs.length > 1 && subCats.length > 1) flags.add('multiple_requests');
else if (subs.length > 1) flags.add('multi_step');
else if ((Number(A.request_count) || 1) > 1) flags.add('multiple_requests');
if (d.request_type === 'client_escalation') flags.add('client_escalation');
if (pre.is_vip) flags.add('vip_sender');
// Only an email the AI is sure is not a work request is logged without a task. If it is not sure, a person decides (Needs Review).
const logOnlyT = Number(cfg.cfg_log_only_confidence ?? cfg.cfg_auto_threshold) || 0.85;
const unsureNotRequest = !!ai && !d.is_request && conf < logOnlyT;
if (unsureNotRequest) flags.add('not_sure_request');

// ---------- due date ----------
let due = null;
let dueSource = ['explicit', 'relative', 'none'].includes(A.due_source) ? A.due_source : 'none';
if (/^\d{4}-\d{2}-\d{2}$/.test(txt(A.due_date))) {
  const parsed = DateTime.fromISO(txt(A.due_date), { zone: TZ }).startOf('day');
  if (parsed.isValid) due = parsed;
}
if (due && due < recvDay) {
  flags.add('due_in_past');
  dueNotes.push('The date in the email (' + due.toISODate() + ') is before the email date, so it was ignored');
  due = null;
}
if (due && !isBiz(due)) {
  const original = due;
  if (dueSource === 'explicit') {
    let moved = prevBiz(due);
    if (moved < recvDay) moved = onOrAfterBiz(recvDay);
    due = moved;
    dueNotes.push(fmt(original) + ' is not a business day, so the task is due on the business day before it: ' + fmt(due));
  } else {
    due = onOrAfterBiz(due);
    dueNotes.push(fmt(original) + ' is not a business day, so the task is due on the next business day: ' + fmt(due));
  }
  flags.add('weekend_deadline_adjusted');
}
if (!due) dueSource = 'none';

// ---------- priority guardrails ----------
let pr = PRIOS.includes(A.priority) ? A.priority : 'normal';
const bd = due ? bizBetween(recvDay, due) : null;
const escalation = flags.has('client_escalation');
const impact = flags.has('active_client_impact');
const legalFin = flags.has('legal') || flags.has('financial_commitment');
if (pr === 'urgent') {
  const justified = impact || (bd !== null && bd === 0) || (legalFin && bd !== null && bd <= 1);
  if (!justified) {
    pr = 'high';
    prNotes.push('Urgent lowered to High: no active client impact and not due today (urgency words alone never make an item Urgent)');
  }
}
const raise = (min, why) => { if (RANK[pr] > RANK[min]) { pr = min; prNotes.push(why); } };
if (impact && bd === 0) raise('urgent', 'Something client-facing is broken and it must be fixed today: Urgent');
if (bd !== null && bd <= 3) raise('high', 'Due in ' + bd + ' business day(s): at least High');
if (escalation) raise('high', 'Client escalation: at least High');
if (impact) raise('high', 'Something client-facing is broken right now: at least High');
if (pre.is_vip) raise('high', 'General Manager request: at least High');

if (!due) {
  const SLA = { urgent: 0, high: 2, normal: 5, low: 10 };
  due = addBiz(recvDay, SLA[pr]);
  dueSource = 'sla_default';
  flags.add('due_inferred');
  dueNotes.push('No date in the email: default for ' + LABEL[pr] + ' priority is ' + (SLA[pr] === 0 ? 'the same business day' : SLA[pr] + ' business days') + ', so ' + fmt(due));
}
let hasTime = false; let hh = 17; let mm = 0;
if (dueSource !== 'sla_default' && /^\d{1,2}:\d{2}$/.test(txt(A.due_time))) {
  const parts = txt(A.due_time).split(':').map(Number);
  if (parts[0] >= 0 && parts[0] < 24 && parts[1] >= 0 && parts[1] < 60) { hh = parts[0]; mm = parts[1]; hasTime = true; }
}
d.priority = pr;
d.priority_num = RANK[pr];
d.due_date = due.toISODate();
d.due_iso = due.set({ hour: hh, minute: mm, second: 0, millisecond: 0 }).toISO({ suppressMilliseconds: true });
d.due_has_time = hasTime;
d.due_source = dueSource;

// ---------- owner from the routing rules table ----------
const rules = pre.routing_rules || [];
const rule = rules.find((r) => r.category === d.category) || rules.find((r) => r.category === 'other');
if (rule) {
  d.owner_name = rule.owner_name;
  d.owner_role = rule.owner_role;
  d.owner_email = rule.owner_email;
  d.assignee_ids = String(rule.clickup_user_id || '').split(',').map((s) => Number(s.trim())).filter((x) => Number.isFinite(x) && x > 0);
} else {
  flags.add('owner_unresolved');
}

// ---------- duplicates: AI match + title similarity ----------
const norm = (s) => lower(s).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const bigrams = (s) => { const t = norm(s).replace(/\s/g, ''); const g = []; for (let i = 0; i < t.length - 1; i++) g.push(t.slice(i, i + 2)); return g; };
const dice = (a, b) => {
  const x = bigrams(a); const y = bigrams(b);
  if (!x.length || !y.length) return 0;
  const counts = new Map();
  x.forEach((g) => counts.set(g, (counts.get(g) || 0) + 1));
  let inter = 0;
  y.forEach((g) => { const c = counts.get(g) || 0; if (c > 0) { inter += 1; counts.set(g, c - 1); } });
  return (2 * inter) / (x.length + y.length);
};
const dupReviewT = Number(cfg.cfg_dup_flag_threshold ?? cfg.cfg_dup_review_threshold) || 0.75;
const dupCommentT = Number(cfg.cfg_dup_comment_threshold) || 0.9;
const cands = pre.task_candidates || [];
let dup = null;
if (ai) {
  const llmId = txt(A.duplicate_of_task_id);
  const llmConf = Math.max(0, Math.min(1, Number(A.duplicate_confidence) || 0));
  if (llmId) {
    const t = cands.find((c) => c.task_id === llmId);
    if (t) dup = { task: t, score: llmConf, via: 'AI match' };
  }
  let best = null;
  cands.forEach((c) => { const s = dice(d.title, c.title); if (!best || s > best.score) best = { task: c, score: s, via: 'title similarity' }; });
  if (best && best.score >= dupReviewT && (!dup || best.score > dup.score)) dup = best;
  if (dup && dup.score < dupReviewT) dup = null;
}
const dupEligible = d.is_request || ['follow_up', 'question', 'change_request'].includes(d.request_type);

// ---------- lane decision ----------
// Policy: a clear work email goes straight to To Do, with the priority set by its content.
// It goes to Needs Review ONLY when a person must decide something before work starts, for one of the reasons below.
// The sender never decides the lane on its own: a clear request from a new or personal address goes to To Do like any other.
// Each Needs Review task shows the exact reason and what the reviewer has to decide.
// Replies and same-person resends become comments; emails the AI is sure are not work requests are only logged.
const REVIEW = {
  ai_failed: { tag: 'review-ai-failed', why: 'The AI could not read this email', decide: 'Read the email and fill in the task by hand' },
  not_sure_request: { tag: 'review-unclear', why: 'It is not clear whether this email needs any work', decide: 'Decide if it needs a task; if not, reject it' },
  ambiguous: { tag: 'review-unclear', why: 'What is being asked is not clear', decide: 'Ask the requester the question below, then move the task to To Do' },
  due_in_past: { tag: 'review-unclear', why: 'The deadline in the email is before the date of the email', decide: 'Confirm the real deadline with the requester' },
  financial_commitment: { tag: 'review-commitment', why: 'The email asks us to approve, pay, sign or commit money or a contract', decide: 'A manager approves it before any work starts' },
  legal: { tag: 'review-commitment', why: 'The email involves a legal or compliance matter', decide: 'A manager approves it before any work starts' },
  hr_sensitive: { tag: 'review-commitment', why: 'The email is about a personal or HR matter concerning someone', decide: 'A manager decides who handles it, confidentially' },
  possible_duplicate: { tag: 'review-duplicate', why: 'It may be the same request as an existing task', decide: 'Merge it with the existing task, or confirm it is a new request' },
  multiple_requests: { tag: 'review-split', why: 'The email asks different teams for different things', decide: 'Split it into one task per team' },
  owner_unresolved: { tag: 'review-owner', why: 'No owner is set for this type of work', decide: 'Assign an owner' },
};
// Notes that do not stop the work: shown on To Do tasks as an Attention list
const ATTENTION = {
  active_client_impact: 'Something client-facing is broken or wrong right now',
  client_escalation: 'Client escalation (complaint or repeated ask)',
  vip_sender: 'Request from the General Manager',
  missing_info: 'Some details are missing: see the question for the requester below',
};
let lane = '';
let reason = '';
if (dup && dupEligible) {
  const sameRequester = dup.task.requester_email && dup.task.requester_email === lower(pre.from_email);
  if (sameRequester && dup.score >= dupCommentT) {
    lane = 'FOLLOW_UP_COMMENT';
    d.target_task_id = dup.task.task_id;
    d.target_task_url = dup.task.task_url || '';
    d.target_task_title = dup.task.title || '';
    d.map_thread = true;
    reason = 'Same requester sent the same request again (' + dup.via + ' ' + dup.score.toFixed(2) + ' with "' + dup.task.title + '"): added as a comment, no duplicate task';
  } else {
    flags.add('possible_duplicate');
  }
}
const review = Object.keys(REVIEW).filter((f) => flags.has(f));
const whyText = (f) => {
  if (f === 'possible_duplicate' && dup) return 'It may be the same request as the existing task "' + dup.task.title + '"';
  if (f === 'multiple_requests' && subs.length > 1) return 'The email asks different teams for ' + subs.length + ' different things';
  return REVIEW[f].why;
};
const attention = Object.keys(ATTENTION).filter((f) => flags.has(f));
if (!lane) {
  if (ai && !d.is_request && !unsureNotRequest) {
    lane = 'LOG_ONLY';
    reason = 'Not a work request (' + d.request_type + ', confidence ' + conf.toFixed(2) + '): logged, no task';
  } else if (review.length) {
    lane = 'HUMAN_REVIEW';
    reason = 'Needs review: ' + review.map(whyText).join('; ') + (aiError && !ai ? ' (' + aiError.slice(0, 160) + ')' : '');
  } else {
    lane = 'AUTO_CREATE';
    reason = 'Clear work request: task in To Do, ' + LABEL[pr] + ' priority' + (attention.length ? '. Attention: ' + attention.map((f) => ATTENTION[f]).join('; ') : '');
  }
}
d.lane = lane;
d.reason = reason;
d.review_reasons = lane === 'HUMAN_REVIEW' ? review : [];

// ---------- tags ----------
const slug = (s) => lower(s).replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const tags = ['intake-bot', slug(d.category)];
if (d.language) tags.push('lang-' + d.language);
if (flags.has('due_inferred')) tags.push('due-inferred');
if (flags.has('active_client_impact')) tags.push('client-impact');
if (flags.has('client_escalation')) tags.push('escalation');
if (flags.has('vip_sender')) tags.push('vip');
if (flags.has('missing_info')) tags.push('has-open-question');
if (lane === 'HUMAN_REVIEW') { tags.push('needs-review'); review.forEach((f) => tags.push(REVIEW[f].tag)); }
d.tags = [...new Set(tags.filter(Boolean))];
d.flags = [...flags];

// ---------- ClickUp description (markdown) ----------
const L = [];
if (lane === 'HUMAN_REVIEW') {
  L.push('**Why this needs review**');
  review.forEach((f) => L.push('- ' + whyText(f)));
  L.push('', '**What to decide**');
  [...new Set(review.map((f) => REVIEW[f].decide))].forEach((x) => L.push('- ' + x));
  L.push('');
}
L.push('**Summary**', d.summary || '(no summary)', '');
if (attention.length && (lane === 'AUTO_CREATE' || lane === 'HUMAN_REVIEW')) {
  L.push('**Attention**');
  attention.forEach((f) => L.push('- ' + ATTENTION[f]));
  L.push('');
}
if (subs.length > 1) {
  L.push(subCats.length > 1 ? '**Asks in this email** (different teams: split into one task per team)' : '**Checklist**');
  subs.forEach((s) => L.push('- [ ] ' + s.ask + (subCats.length > 1 ? ' (' + s.category + ')' : '')));
  L.push('');
} else if (txt(A.deliverable)) {
  L.push('**Deliverable:** ' + txt(A.deliverable), '');
}
const timeText = hasTime ? ' ' + String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0') : '';
L.push('**Due:** ' + fmt(due) + timeText + ' (' + (dueSource === 'sla_default' ? 'inferred from the ' + LABEL[pr] + ' SLA, no date in the email' : dueSource + (txt(A.due_phrase) ? ': "' + txt(A.due_phrase) + '"' : '')) + ')');
dueNotes.forEach((x) => L.push('- ' + x));
L.push('**Priority:** ' + LABEL[pr] + (txt(A.priority_reason) ? ' (' + txt(A.priority_reason) + ')' : ''));
prNotes.forEach((x) => L.push('- ' + x));
L.push('**Suggested owner:** ' + (d.owner_name ? d.owner_name + ', ' + d.owner_role : 'unassigned'));
if (d.client_name) L.push('**Client:** ' + d.client_name);
if (txt(A.clarifying_question)) L.push('', '**Question to send the requester:** ' + txt(A.clarifying_question));
if (flags.has('possible_duplicate') && dup) {
  L.push('', '**Possible duplicate of:** ' + dup.task.title + (dup.task.task_url ? ' (' + dup.task.task_url + ')' : ' [' + dup.task.task_id + ']') + ', ' + dup.via + ' ' + dup.score.toFixed(2));
}
L.push('', '---');
const SENDER_LABEL = { internal: 'Internal colleague', client: 'client', unknown_external: 'external sender' };
L.push('**Requester:** ' + (pre.from_name || '') + ' (' + pre.from_email + '), ' + (SENDER_LABEL[pre.sender_kind] || 'external sender') + (pre.sender_client ? ', ' + pre.sender_client : ''));
L.push('**Email:** "' + pre.subject + '", received ' + pre.received_local + ' (Amman)');
L.push('**Thread ID:** `' + pre.thread_id + '`  **Message-ID:** `' + pre.message_id + '`');
L.push('**Decision:** ' + reason);
L.push('**AI:** confidence ' + d.confidence.toFixed(2) + ', model ' + (cfg.cfg_model || '') + ', prompt ' + (cfg.cfg_prompt_version || '') + (d.flags.length ? ', flags: ' + d.flags.join(', ') : ''));
if (txt(A.rationale)) L.push('**Why:** ' + txt(A.rationale));
L.push('', '**Original email (excerpt)**');
String(pre.body_clean || '').slice(0, 1200).split('\n').forEach((l) => L.push('> ' + l));
d.task_title = d.title;
d.task_description = L.join('\n');

if (lane === 'FOLLOW_UP_COMMENT') {
  d.comment_text = 'Possible resend of this request from ' + (pre.from_name || pre.from_email) + ' <' + pre.from_email + '> on ' + pre.received_local
    + ' (Amman), in a new email thread.\nSubject: ' + pre.subject + '\nMatch: ' + dup.via + ' ' + dup.score.toFixed(2) + '\n\n'
    + String(pre.body_clean || '').slice(0, 1500) + '\n\n(Added by the intake automation instead of creating a duplicate task.)';
}
d.ai_rationale = txt(A.rationale);
d.clarifying_question = txt(A.clarifying_question);
if (lane === 'LOG_ONLY' || lane === 'FOLLOW_UP_COMMENT') {
  // No new task: priority, due date and owner would only add noise to the log
  d.priority = ''; d.priority_num = null; d.due_date = ''; d.due_iso = ''; d.due_has_time = false; d.due_source = '';
  d.owner_name = ''; d.owner_role = ''; d.owner_email = ''; d.assignee_ids = [];
  d.flags = d.flags.filter((f) => f !== 'due_inferred' && f !== 'weekend_deadline_adjusted');
  if (lane === 'LOG_ONLY') d.category = '';
}

['prompt_email', 'prompt_sender', 'prompt_calendar', 'prompt_recent_tasks', 'task_candidates', 'routing_rules'].forEach((k) => { delete d[k]; });
return { json: d };

// One decision shape for every lane, plus the route the Switch uses (live ClickUp or mock table).
// Clear work requests go to To Do (Requests list); items with a specific review reason go to Needs Review (Triage list);
// replies and resends become comments; non-work mail is only logged.
const cfg = $('Settings').first().json;
const hash = (s) => {
  let h = 5381;
  for (const ch of String(s)) h = ((h << 5) + h + ch.charCodeAt(0)) >>> 0;
  return h.toString(36).toUpperCase();
};
return $input.all().map((item) => {
  const d = { ...item.json };
  ['prompt_email', 'prompt_sender', 'prompt_calendar', 'prompt_recent_tasks', 'task_candidates', 'routing_rules'].forEach((k) => { delete d[k]; });
  d.cfg_mode = String(cfg.cfg_mode || 'mock').toLowerCase() === 'live' ? 'live' : 'mock';
  d.cfg_team_id = String(cfg.cfg_team_id || '');
  d.cfg_space_id = String(cfg.cfg_space_id || '');
  d.cfg_requests_list_id = String(cfg.cfg_requests_list_id || '');
  d.cfg_triage_list_id = String(cfg.cfg_triage_list_id || '');
  if (!['AUTO_CREATE', 'HUMAN_REVIEW', 'FOLLOW_UP_COMMENT', 'LOG_ONLY'].includes(d.lane)) {
    // Safety net: an unknown or missing lane goes to a person, so no email is lost
    d.reason = 'Needs review: no clear decision was made for this email' + (d.reason ? ' (' + d.reason + ')' : '');
    d.lane = 'HUMAN_REVIEW';
    if (!Array.isArray(d.tags)) d.tags = [];
    d.tags.push('needs-review');
  }
  d.creates_task = d.lane === 'AUTO_CREATE' || d.lane === 'HUMAN_REVIEW';
  d.task_list = d.lane === 'AUTO_CREATE' ? 'Requests' : (d.lane === 'HUMAN_REVIEW' ? 'Needs Review' : '');
  d.task_status = d.lane === 'AUTO_CREATE' ? 'to do' : (d.lane === 'HUMAN_REVIEW' ? 'needs review' : '');
  d.mock_task_id = d.creates_task ? 'MOCK-' + hash(d.message_id + '|' + (d.sample_id || '')) : '';
  if (!Array.isArray(d.tags)) d.tags = [];
  if (!Array.isArray(d.flags)) d.flags = [];
  if (!Array.isArray(d.assignee_ids)) d.assignee_ids = [];
  if (d.creates_task && !d.task_title) d.task_title = d.title || ('Read and handle email: ' + (d.subject || '(no subject)'));
  if (d.creates_task && !d.task_description) d.task_description = '**Why this needs review**\n- ' + d.reason + '\n\nEmail from ' + d.from_email + ': ' + (d.subject || '') + '\n\n' + String(d.body_clean || '').slice(0, 1200);
  if (d.creates_task && !d.priority_num) { d.priority = d.priority || 'normal'; d.priority_num = 3; }
  let route = 'log_only';
  if (d.lane !== 'LOG_ONLY') {
    if (d.cfg_mode === 'live') route = { AUTO_CREATE: 'create_requests', HUMAN_REVIEW: 'create_review', FOLLOW_UP_COMMENT: 'comment' }[d.lane];
    else route = 'mock';
  }
  d.route = route;
  d.processed_at = DateTime.now().setZone(cfg.cfg_timezone || 'Asia/Amman').toISO({ suppressMilliseconds: true });
  d.execution_id = String($execution.id);
  return { json: d };
});

// Joins the decision with the ClickUp (or mock) result. Every email gets exactly one log row.
// The row also carries what the monitoring dashboard needs: who sent it, why it went to its lane,
// and, when something failed, which node failed and what it said.
const d = $('Finalize decision').first().json;
const r = ($input.first() && $input.first().json) || {};
const errText = (x) => String((x && (x.message || x.description)) || x || '').slice(0, 300);
const join = (x) => (Array.isArray(x) ? x.filter(Boolean).join(', ') : String(x || ''));
const NODE_BY_ROUTE = {
  create_requests: 'ClickUp: create task in Requests',
  create_review: 'ClickUp: create task in Needs Review',
  comment: 'ClickUp: comment on existing task',
  mock: 'Mock: record ClickUp action',
};
let taskId = '';
let taskUrl = '';
let actionOk = true;
let note = '';
let actionError = '';
if (d.route === 'create_requests' || d.route === 'create_review') {
  taskId = String(r.id || '');
  taskUrl = String(r.url || '');
  if (!taskId) { actionOk = false; actionError = errText(r.error) || 'no task id returned'; note = 'ClickUp task was not created: ' + actionError; }
} else if (d.route === 'comment') {
  taskId = String(d.target_task_id || '');
  taskUrl = String(d.target_task_url || '');
  if (r.error || !(r.id || r.hist_id)) { actionOk = false; actionError = errText(r.error) || 'no comment id returned'; note = 'ClickUp comment failed: ' + actionError; }
} else if (d.route === 'mock') {
  taskId = d.lane === 'FOLLOW_UP_COMMENT' ? String(d.target_task_id || '') : String(d.mock_task_id || '');
  taskUrl = d.lane === 'FOLLOW_UP_COMMENT' ? String(d.target_task_url || '') : '';
  if (r.error) { actionOk = false; actionError = errText(r.error); note = 'Mock write failed: ' + actionError; }
}

// Where it failed and what the service said (empty when nothing failed)
let errorNode = '';
let errorMessage = '';
if (!actionOk) {
  errorNode = NODE_BY_ROUTE[d.route] || 'ClickUp';
  errorMessage = note;
} else if (d.ai_ok === false) {
  // The business rules put the AI error text in brackets at the end of the reason
  const m = String(d.reason || '').match(/\(([^()]*)\)\s*$/);
  const aiError = String(d.ai_error || (m ? m[1] : '')).slice(0, 300);
  errorNode = 'AI triage';
  errorMessage = 'The AI step did not return a usable answer' + (aiError ? ': ' + aiError : '') + '. The email went to Needs Review.';
}

// Seconds from the email arriving to it being handled (real Gmail emails only; samples have fixed dates)
let latency = null;
if (d.source === 'gmail' && d.received_at && d.processed_at) {
  const a = Date.parse(d.received_at);
  const b = Date.parse(d.processed_at);
  if (Number.isFinite(a) && Number.isFinite(b) && b >= a) latency = Math.round((b - a) / 1000);
}

const createdTask = d.creates_task && actionOk && !!taskId;
const mapThread = actionOk && !!taskId && (createdTask || (d.lane === 'FOLLOW_UP_COMMENT' && d.map_thread === true));
return [{
  json: {
    message_id: d.message_id,
    thread_id: d.thread_id,
    received_at: d.received_at,
    from_email: d.from_email,
    from_name: d.from_name || '',
    sender_kind: d.sender_kind || '',
    subject: d.subject,
    title: d.lane === 'FOLLOW_UP_COMMENT' ? (d.target_task_title || d.title || '') : (d.task_title || ''),
    lane: d.lane,
    reason: note ? d.reason + ' | ' + note : d.reason,
    review_reasons: join(d.review_reasons),
    request_type: d.request_type || '',
    category: d.category || '',
    priority: d.priority || '',
    confidence: typeof d.confidence === 'number' ? d.confidence : null,
    owner: d.owner_name || '',
    due_date: d.due_date || '',
    due_source: d.due_source || '',
    language: d.language || '',
    client_name: d.client_name || '',
    list_name: d.lane === 'FOLLOW_UP_COMMENT' ? 'existing task' : (d.task_list || ''),
    task_id: taskId,
    task_url: taskUrl,
    target_task_id: String(d.target_task_id || ''),
    ai_ok: typeof d.ai_ok === 'boolean' ? d.ai_ok : null,
    action_ok: actionOk,
    error_node: errorNode,
    error_message: errorMessage.slice(0, 500),
    flags: join(d.flags),
    tags: join(d.tags),
    mode: d.cfg_mode,
    source: d.source,
    sample_id: d.sample_id || '',
    execution_id: d.execution_id,
    processed_at: d.processed_at,
    latency_sec: latency,
    summary: String(d.summary || '').slice(0, 500),
    clarifying_question: String(d.clarifying_question || '').slice(0, 300),
    ai_rationale: String(d.ai_rationale || '').slice(0, 400),
    map_thread: mapThread,
    map_list_name: d.lane === 'FOLLOW_UP_COMMENT' ? 'existing task' : (d.task_list || ''),
    map_title: d.lane === 'FOLLOW_UP_COMMENT' ? (d.target_task_title || d.title || '') : (d.task_title || ''),
    map_client_name: d.client_name || '',
    map_category: d.category || '',
  },
}];
